// Ring-buffer queue over a 1-row r32float storage texture.
// Each thread attempts to dequeue one element by CAS on head.
// queue_tex dims: width = capacity, height >= row+1
// dequeue_out: first row receives popped values at x = thread index

struct QueuePtrs {
  head: atomic<u32>;
  tail: atomic<u32>;
  capacity: u32;
  row: u32;
};

@group(0) @binding(3) var queue_tex: texture_storage_2d<r32float, read_write>;
@group(0) @binding(4) var<storage, read_write> ptrs: QueuePtrs;
@group(0) @binding(5) var dq_out: texture_storage_2d<r32float, write>;

fn wrap(i: u32, cap: u32) -> u32 { return select(i, i - cap, i >= cap); }

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let lane = gid.x;
  let cap = ptrs.capacity;
  if (cap == 0u) { return; }

  // Fast-empty check
  if (atomicLoad(&ptrs.head) == atomicLoad(&ptrs.tail)) { return; }

  // Try to claim one slot by incrementing head
  var claimed = false;
  var my_idx = 0u;
  loop {
    let old_head = atomicLoad(&ptrs.head);
    let tail = atomicLoad(&ptrs.tail);
    if (old_head == tail) { break; } // empty now
    let next = wrap(old_head + 1u, cap);
    let cas = atomicCompareExchangeWeak(&ptrs.head, old_head, next);
    if (cas.exchanged) {
      claimed = true;
      my_idx = old_head;
      break;
    }
    continuing { }
  }

  if (!claimed) { return; }

  // Read value and write to output row 0 at x = lane
  let row = i32(ptrs.row);
  let px = vec2<i32>(i32(my_idx), row);
  let val = textureLoad(queue_tex, px).r;
  textureStore(dq_out, vec2<u32>(lane, 0u), vec4<f32>(val, 0.0, 0.0, 1.0));

  // Optional: clear the consumed slot (not required for correctness)
  textureStore(queue_tex, vec2<u32>(my_idx, ptrs.row), vec4<f32>(0.0,0.0,0.0,1.0));
}

// Bilateral filter followed by temporal EMA in a single pass.
// Ping-pong by writing both denoised_out and next_prev_tex the same value.

struct DenoiseParams {
  size: vec2<u32>,
  sigma_s: f32,   // spatial sigma (pixels)
  sigma_r: f32,   // range sigma (0..1)
  alpha: f32      // EMA blend (0..1), 0=stick to prev, 1=trust current
};

@group(0) @binding(0) var<uniform> U: DenoiseParams;
@group(0) @binding(1) var src_tex: texture_2d<f32>;
@group(0) @binding(2) var prev_tex: texture_2d<f32>;
@group(0) @binding(3) var out_tex: texture_storage_2d<rgba8unorm, write>;
@group(0) @binding(4) var out_next_prev: texture_storage_2d<rgba8unorm, write>;

fn clampCoord(p: vec2<i32>, wh: vec2<i32>) -> vec2<i32> {
  return clamp(p, vec2<i32>(0,0), wh - vec2<i32>(1,1));
}

fn luma(c: vec3<f32>) -> f32 { return dot(c, vec3<f32>(0.299, 0.587, 0.114)); }

@compute @workgroup_size(16,16)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  if (any(gid.xy >= U.size)) { return; }
  let wh_i = vec2<i32>(i32(U.size.x), i32(U.size.y));
  let p = vec2<i32>(i32(gid.x), i32(gid.y));

  // --- Bilateral ---
  let center = textureLoad(src_tex, p, 0).rgb;
  let center_y = luma(center);
  let r = u32(ceil(2.0 * max(U.sigma_s, 0.5)));
  var num = vec3<f32>(0.0);
  var den = 0.0;
  for (var dy: i32 = -i32(r); dy <= i32(r); dy++) {
    for (var dx: i32 = -i32(r); dx <= i32(r); dx++) {
      let q = clampCoord(p + vec2<i32>(dx,dy), wh_i);
      let s = textureLoad(src_tex, q, 0).rgb;
      let sd = length(vec2<f32>(f32(dx), f32(dy)));
      let wd = exp(-0.5 * (sd*sd) / max(U.sigma_s*U.sigma_s, 1e-5));
      let rd = center_y - luma(s);
      let wr = exp(-0.5 * (rd*rd) / max(U.sigma_r*U.sigma_r, 1e-6));
      let w = wd * wr;
      num += s * w;
      den += w;
    }
  }
  let bilateral_rgb = select(center, num / max(den, 1e-6), den > 0.0);

  // --- Temporal EMA ---
  let prev_rgb = textureLoad(prev_tex, p, 0).rgb;
  let a = clamp(U.alpha, 0.0, 1.0);
  let ema_rgb = mix(prev_rgb, bilateral_rgb, a);
  let out_px = vec4<f32>(ema_rgb, 1.0);
  textureStore(out_tex, vec2<u32>(gid.xy), out_px);
  textureStore(out_next_prev, vec2<u32>(gid.xy), out_px);
}

// Ring-buffer enqueue over a 1-row r32float storage texture.
// Each thread attempts to enqueue one value by CAS on tail.
// enqueue_src: read values from row 0 at x = thread index (use .r)
// queue_tex dims: width = capacity, height >= row+1
// enqueued_mask: row 0 gets 1 if this lane enqueued, else 0

struct QueuePtrs {
  head: atomic<u32>;
  tail: atomic<u32>;
  capacity: u32;
  row: u32;
};

@group(0) @binding(2) var enqueue_src: texture_2d<f32>;
@group(0) @binding(3) var queue_tex: texture_storage_2d<r32float, read_write>;
@group(0) @binding(4) var<storage, read_write> ptrs: QueuePtrs;
@group(0) @binding(5) var enq_mask: texture_storage_2d<r32float, write>;

fn wrap(i: u32, cap: u32) -> u32 { return select(i, i - cap, i >= cap); }

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let lane = gid.x;
  let cap = ptrs.capacity;
  if (cap == 0u) { return; }

  var claimed = false;
  var my_idx = 0u;
  loop {
    let old_tail = atomicLoad(&ptrs.tail);
    let head = atomicLoad(&ptrs.head);
    let next = wrap(old_tail + 1u, cap);
    // Full if next catches head
    if (next == head) { break; }
    let cas = atomicCompareExchangeWeak(&ptrs.tail, old_tail, next);
    if (cas.exchanged) {
      claimed = true;
      my_idx = old_tail;
      break;
    }
    continuing { }
  }

  var wrote = 0.0;
  if (claimed) {
    let val = textureLoad(enqueue_src, vec2<i32>(i32(lane), 0), 0).r;
    textureStore(queue_tex, vec2<u32>(my_idx, ptrs.row), vec4<f32>(val, 0.0, 0.0, 1.0));
    wrote = 1.0;
  }
  textureStore(enq_mask, vec2<u32>(lane, 0u), vec4<f32>(wrote, 0.0, 0.0, 1.0));
}

// Dequeue one job per lane and bump a per-job atomic counter.
// Job ID is derived from the dequeued value (rounded, clamped).
// processed_ids_out row 0 gets the processed job id (or -1 if none).

struct QueuePtrs {
  head: atomic<u32>;
  tail: atomic<u32>;
  capacity: u32;
  row: u32;
};

struct SchedulerParams {
  num_counters: u32;
  _pad0: vec3<u32>;
};

struct JobCounters {
  counts: array<atomic<u32>>;
};

@group(0) @binding(0) var<uniform> P: SchedulerParams;
@group(0) @binding(3) var queue_tex: texture_storage_2d<r32float, read_write>;
@group(0) @binding(4) var<storage, read_write> ptrs: QueuePtrs;
@group(0) @binding(5) var processed_ids_out: texture_storage_2d<r32float, write>;
@group(0) @binding(6) var<storage, read_write> JC: JobCounters;

fn wrap(i: u32, cap: u32) -> u32 { return select(i, i - cap, i >= cap); }

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let lane = gid.x;
  let cap = ptrs.capacity;
  if (cap == 0u || P.num_counters == 0u) { return; }

  // Fast-empty
  if (atomicLoad(&ptrs.head) == atomicLoad(&ptrs.tail)) {
    textureStore(processed_ids_out, vec2<u32>(lane, 0u), vec4<f32>(-1.0,0.0,0.0,1.0));
    return;
  }

  // Claim one slot by incrementing head
  var claimed = false;
  var my_idx = 0u;
  loop {
    let old_head = atomicLoad(&ptrs.head);
    let tail = atomicLoad(&ptrs.tail);
    if (old_head == tail) { break; }
    let next = wrap(old_head + 1u, cap);
    let cas = atomicCompareExchangeWeak(&ptrs.head, old_head, next);
    if (cas.exchanged) {
      claimed = true;
      my_idx = old_head;
      break;
    }
    continuing { }
  }

  if (!claimed) {
    textureStore(processed_ids_out, vec2<u32>(lane, 0u), vec4<f32>(-1.0,0.0,0.0,1.0));
    return;
  }

  // Read job value, map to counter index, bump
  let px = vec2<i32>(i32(my_idx), i32(ptrs.row));
  let val = textureLoad(queue_tex, px).r;
  let jid = clamp(i32(round(val)), 0, i32(P.num_counters) - 1);
  atomicAdd(&JC.counts[u32(jid)], 1u);
  textureStore(processed_ids_out, vec2<u32>(lane, 0u), vec4<f32>(f32(jid),0.0,0.0,1.0));

  // Optional: clear consumed slot
  textureStore(queue_tex, vec2<u32>(my_idx, ptrs.row), vec4<f32>(0.0,0.0,0.0,1.0));
}
